	@Test
	void simultaneousFirstOpensAndIncrementsKeepOneResidentHistory() throws Exception {
		int workers = 8;
		int rounds = 100;
		LmdbNativeShapeCounter counter = new LmdbNativeShapeCounter(1);
		CyclicBarrier barrier = new CyclicBarrier(workers);
		ExecutorService executor = Executors.newFixedThreadPool(workers);
		try {
			List<Future<List<Long>>> futures = new ArrayList<>();
			for (int worker = 0; worker < workers; worker++) {
				futures.add(executor.submit(() -> {
					List<Long> observed = new ArrayList<>();
					for (int round = 0; round < rounds; round++) {
						barrier.await(10L, TimeUnit.SECONDS);
						observed.add(counter.increment("shared"));
					}
					return observed;
				}));
			}
			Set<Long> observed = new HashSet<>();
			for (Future<List<Long>> future : futures) {
				observed.addAll(future.get(10L, TimeUnit.SECONDS));
			}
			assertEquals(workers * rounds, observed.size(), "every simultaneous open gets a distinct count");
			for (long count = 1L; count <= workers * rounds; count++) {
				assertTrue(observed.contains(count));
			}
			assertEquals(workers * rounds + 1L, counter.increment("shared"));
			assertEquals(1L, counter.size());
		} finally {
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(10L, TimeUnit.SECONDS));
		}
	}

	@Test
	void concurrentDistinctShapesStayWithinCapacity() throws Exception {
		int workers = 8;
		int maximum = 16;
		LmdbNativeShapeCounter counter = new LmdbNativeShapeCounter(maximum);
		CyclicBarrier barrier = new CyclicBarrier(workers);
		ExecutorService executor = Executors.newFixedThreadPool(workers);
		try {
			List<Future<?>> futures = new ArrayList<>();
			for (int worker = 0; worker < workers; worker++) {
				int owner = worker;
				futures.add(executor.submit(() -> {
					for (int round = 0; round < 100; round++) {
						barrier.await(10L, TimeUnit.SECONDS);
						counter.increment(owner + ":" + round);
						barrier.await(10L, TimeUnit.SECONDS);
						assertTrue(counter.size() <= maximum);
					}
					return null;
				}));
			}
			for (Future<?> future : futures) {
				future.get(10L, TimeUnit.SECONDS);
			}
			assertEquals(maximum, counter.size());
		} finally {
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(10L, TimeUnit.SECONDS));
		}
	}
